"""Mixed tactile env variant with per-sensor binary gates and global gate."""

from __future__ import annotations

import torch

from isaaclab.utils import configclass

from .vt_mixed_box import (
    OccludedGraspingVisionMixedTactileBoxCfg,
    OccludedGraspingVisionMixedTactileBoxEnv,
)


@configclass
class OccludedGraspingVisionMixedSensorGateBoxCfg(OccludedGraspingVisionMixedTactileBoxCfg):
    """Mixed tactile config with explicit per-sensor gates used by the policy."""

    def __post_init__(self):
        super().__post_init__()
        self.observation_space = {
            **self.observation_space,
            "tactile_sensor_gates": 4,
            "tactile_global_gate": 1,
        }


class OccludedGraspingVisionMixedSensorGateBoxEnv(OccludedGraspingVisionMixedTactileBoxEnv):
    """Expose per-sensor/global gates without zeroing tactile features in env."""

    cfg: OccludedGraspingVisionMixedSensorGateBoxCfg

    _TACTILE_FEATURE_KEYS = (
        "tactile_left_rgb",
        "tactile_right_rgb",
        "tactile_left_down_depth",
        "tactile_right_down_depth",
    )

    def __init__(self, cfg: OccludedGraspingVisionMixedSensorGateBoxCfg, render_mode: str | None = None, **kwargs):
        super().__init__(cfg, render_mode, **kwargs)
        self._latest_sensor_gate_means = {
            "left": torch.tensor(0.0, device=self.device),
            "right": torch.tensor(0.0, device=self.device),
            "left_down": torch.tensor(0.0, device=self.device),
            "right_down": torch.tensor(0.0, device=self.device),
        }

    def _get_observations(self) -> dict[str, dict[str, torch.Tensor]]:
        observations = super()._get_observations()
        obs = observations["policy"]

        sensor_gates = obs.get("tactile_contact_bits")
        if sensor_gates is None:
            sensor_gates = torch.zeros((self.num_envs, 4), dtype=torch.float32, device=self.device)
        else:
            sensor_gates = sensor_gates.to(device=self.device, dtype=torch.float32).reshape(self.num_envs, -1).clamp(0.0, 1.0)
            if sensor_gates.shape[1] != 4:
                if sensor_gates.shape[1] > 4:
                    sensor_gates = sensor_gates[:, :4]
                else:
                    pad = torch.zeros((self.num_envs, 4 - sensor_gates.shape[1]), dtype=torch.float32, device=self.device)
                    sensor_gates = torch.cat([sensor_gates, pad], dim=-1)

        # Align with vt_mixed_box semantics: tactile validity is based on recent
        # contact history (not only current-step sensor gates).
        if hasattr(self, "_tactile_contact_history"):
            global_gate = self._tactile_contact_history.max(dim=1).values.max(dim=-1, keepdim=True).values
        else:
            global_gate = sensor_gates.max(dim=-1, keepdim=True).values
        obs["tactile_sensor_gates"] = sensor_gates
        obs["tactile_global_gate"] = global_gate
        obs["tactile_valid"] = global_gate

        log = self.extras.setdefault("log", {})
        log["info/tactile_global_gate_mean"] = global_gate.mean().detach()
        log["info/tactile_sensor_gate_left"] = sensor_gates[:, 0].mean().detach()
        log["info/tactile_sensor_gate_right"] = sensor_gates[:, 1].mean().detach()
        log["info/tactile_sensor_gate_left_down"] = sensor_gates[:, 2].mean().detach()
        log["info/tactile_sensor_gate_right_down"] = sensor_gates[:, 3].mean().detach()
        self._latest_sensor_gate_means["left"] = log["info/tactile_sensor_gate_left"]
        self._latest_sensor_gate_means["right"] = log["info/tactile_sensor_gate_right"]
        self._latest_sensor_gate_means["left_down"] = log["info/tactile_sensor_gate_left_down"]
        self._latest_sensor_gate_means["right_down"] = log["info/tactile_sensor_gate_right_down"]

        return {"policy": obs}

    def _get_rewards(self) -> torch.Tensor:
        rewards = super()._get_rewards()
        if self.cfg.reward_print_interval > 0 and (self.step_count % self.cfg.reward_print_interval == 0):
            try:
                print(
                    f"[Sensor Gates] step {self.step_count}: "
                    f"left={self._latest_sensor_gate_means['left'].item():.4f}, "
                    f"right={self._latest_sensor_gate_means['right'].item():.4f}, "
                    f"left_down={self._latest_sensor_gate_means['left_down'].item():.4f}, "
                    f"right_down={self._latest_sensor_gate_means['right_down'].item():.4f}"
                )
            except Exception:
                pass
        return rewards

    def _reset_idx(self, env_ids: torch.Tensor):
        super()._reset_idx(env_ids)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
